with filtered as (select id, city, segment, is_active, credit_limit, lower(city) as city_lower, date_trunc('WEEK', signup_date) as signup_date_period, coalesce(city, 'NONE') as city_filled from customers where city is not null and signup_date > date '2023-03-20') select id, city, segment, credit_limit, city_lower, signup_date_period from filtered qualify row_number() over (partition by city order by credit_limit desc nulls first, id asc) = 1;
